"""Static SVG checks for figures generated by the framework."""

import re
import xml.etree.ElementTree as ET
from typing import Dict, List

SVG_NS = "{http://www.w3.org/2000/svg}"
EXTERNAL_PREFIX = ("http://", "https://", "file://", "//")
EVENT_ATTR = re.compile(r"^on[a-z]+$", re.I)


def audit_svg(svg: str) -> Dict[str, object]:
    errors: List[str] = []
    warnings: List[str] = []
    checks: Dict[str, object] = {}
    if "<!doctype" in svg.lower() or "<!entity" in svg.lower():
        return {"ok": False, "errors": ["DOCTYPE/ENTITY is not allowed"], "warnings": [], "checks": {}}
    try:
        root = ET.fromstring(svg)
    except ET.ParseError as exc:
        return {"ok": False, "errors": ["XML parse error: %s" % exc], "warnings": [], "checks": {}}

    checks["root"] = root.tag == SVG_NS + "svg"
    if not checks["root"]:
        errors.append("root element is not svg")
    width = root.get("width", "")
    height = root.get("height", "")
    view_box = root.get("viewBox", "")
    checks["size"] = bool(width and height and view_box)
    if not checks["size"]:
        errors.append("svg needs width, height and viewBox")

    ids: Dict[str, int] = {}
    text_count = 0
    image_count = 0
    for elem in root.iter():
        tag = elem.tag.split("}")[-1]
        if tag in ("script", "foreignObject"):
            errors.append("forbidden element: " + tag)
        if tag == "image":
            image_count += 1
            href = elem.get("href") or elem.get("{http://www.w3.org/1999/xlink}href") or ""
            if not href.startswith("data:image/"):
                errors.append("external image is not allowed")
        if tag == "text":
            text_count += 1
            if not "".join(elem.itertext()).strip():
                errors.append("empty text element: " + str(elem.get("id", "?")))
        for attr, value in elem.attrib.items():
            if EVENT_ATTR.match(attr.split("}")[-1]):
                errors.append("event handler attribute is not allowed: " + attr)
            if attr.split("}")[-1] in ("href", "xlink:href") and value and not value.startswith(("#", "data:image/")):
                if value.startswith(EXTERNAL_PREFIX) or value.lower().startswith("javascript:"):
                    errors.append("external reference is not allowed: " + value)
        elem_id = elem.get("id")
        if elem_id:
            ids[elem_id] = ids.get(elem_id, 0) + 1

    duplicates = [key for key, count in ids.items() if count > 1]
    checks["ids_unique"] = not duplicates
    if duplicates:
        errors.append("duplicate ids: " + ", ".join(duplicates))
    checks["text_count"] = text_count
    checks["image_count"] = image_count
    checks["role_img"] = root.get("role") == "img"
    checks["labelled"] = bool(root.get("aria-labelledby"))
    if not checks["role_img"]:
        warnings.append("root svg has no role=img")
    if not checks["labelled"]:
        warnings.append("root svg has no aria-labelledby")
    checks["has_title"] = any(elem.tag == SVG_NS + "title" and elem.get("id") == "fig-title" for elem in root.iter())
    checks["has_desc"] = any(elem.tag == SVG_NS + "desc" and elem.get("id") == "fig-desc" for elem in root.iter())
    labels = (root.get("aria-labelledby") or "").split()
    checks["aria_targets"] = bool(labels) and all(label in ids for label in labels)
    if not checks["has_title"] or not checks["has_desc"]:
        errors.append("svg needs <title id=fig-title> and <desc id=fig-desc>")
    if not checks["aria_targets"]:
        errors.append("aria-labelledby must point to existing ids")
    return {"ok": not errors, "errors": errors, "warnings": warnings, "checks": checks}
